My AI review barked about chown/chmod in a rootless environment with unpack.  Here's what it suggested:

```
diff --git a/add.go b/add.go
index e5d5d93aea..0000000000 100644
--- a/add.go
+++ b/add.go
@@ -220,14 +220,64 @@ func getURL(ctx context.Context, src string, chown *idtools.IDPair, mountpoint,
 	}

 	if expand && archiveFile != nil && copier.IsArchivePath(archiveFile.Name()) {
 		rc, _, err := compression.AutoDecompress(archiveFile)
 		if err != nil {
 			return fmt.Errorf("decompressing %q: %w", src, err)
 		}
 		defer rc.Close()
-		if _, err := io.Copy(writer, rc); err != nil {
-			return fmt.Errorf("writing decompressed content from %q to tar stream: %w", src, err)
+
+		// Rewrite headers so --chown/--chmod/--timestamp match the
+		// non-expand remote path (and local ADD metadata flags).
+		var mod *mode.Set
+		if chmod != "" {
+			p, err := mode.Parse(chmod)
+			if err != nil {
+				return fmt.Errorf("parsing chmod %q: %w", chmod, err)
+			}
+			mod = &p
+		}
+
+		tr := tar.NewReader(rc)
+		tw := tar.NewWriter(writer)
+		defer tw.Close()
+		for {
+			hdr, err := tr.Next()
+			if err == io.EOF {
+				break
+			}
+			if err != nil {
+				return fmt.Errorf("reading archive entry from %q: %w", src, err)
+			}
+			if chown != nil {
+				hdr.Uid = chown.UID
+				hdr.Gid = chown.GID
+			}
+			if mod != nil {
+				hdr.Mode = int64(mod.Apply(os.FileMode(hdr.Mode)))
+			}
+			if timestamp != nil {
+				ts := timestamp.UTC()
+				hdr.ModTime = ts
+				if !hdr.AccessTime.IsZero() {
+					hdr.AccessTime = ts
+				}
+				if !hdr.ChangeTime.IsZero() {
+					hdr.ChangeTime = ts
+				}
+			}
+			if err := tw.WriteHeader(hdr); err != nil {
+				return fmt.Errorf("writing header for %q from %q: %w", hdr.Name, src, err)
+			}
+			if hdr.Size > 0 {
+				if _, err := io.Copy(tw, tr); err != nil {
+					return fmt.Errorf("writing content for %q from %q: %w", hdr.Name, src, err)
+				}
+			}
 		}
 		if digester != nil {
 			if responseDigest := digester.Digest(); responseDigest != srcDigest {
 				return fmt.Errorf("unexpected response digest for %q: %s, want %s", src, responseDigest, srcDigest)
 			}
 		}
 		return nil
 	}
```

YMMV
